CREATE OR REPLACE FUNCTION public.can_instructor_access_student(_instructor_id uuid,_student_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.student_instructors WHERE instructor_id=_instructor_id AND student_id=_student_id) OR EXISTS(SELECT 1 FROM public.cover_sessions WHERE cover_instructor_id=_instructor_id AND student_id=_student_id) OR EXISTS(SELECT 1 FROM public.production_enrollments WHERE instructor_id=_instructor_id AND student_id=_student_id AND active) $$;
CREATE FUNCTION public.validate_production_submission() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF TG_OP='UPDATE' AND (NEW.enrollment_id IS DISTINCT FROM OLD.enrollment_id OR NEW.module_id IS DISTINCT FROM OLD.module_id OR NEW.block_id IS DISTINCT FROM OLD.block_id OR NEW.storage_path IS DISTINCT FROM OLD.storage_path OR NEW.media_url IS DISTINCT FROM OLD.media_url OR NEW.student_note IS DISTINCT FROM OLD.student_note) THEN RAISE EXCEPTION 'Review cannot change submitted work'; END IF; IF coalesce(NEW.storage_path,'')='' AND NEW.media_url !~ '^https://[^ ]+' THEN RAISE EXCEPTION 'An audio file or HTTPS link is required'; END IF; RETURN NEW; END $$;
CREATE TRIGGER validate_production_submission BEFORE INSERT OR UPDATE ON public.production_submissions FOR EACH ROW EXECUTE FUNCTION public.validate_production_submission();